/**
 * Unit tests: components/payments/tabs/DisputesTab
 *
 * Coverage (5 cases):
 *  1. Empty state — "No disputes on record."
 *  2. Urgency banner — dispute evidence_due_by < 72h
 *  3. Submit now — calls submit endpoint, refreshes list
 *  4. View evidence — opens evidence drawer (SheetContent)
 *  5. Intentional skip — artist role tab hiding (covered by E2E navigation tests)
 *
 * No DB required. Global fetch mocked per test.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, waitFor, fireEvent } from '@testing-library/react'

// ── Browser stubs ──────────────────────────────────────────────────────────────

if (typeof window !== 'undefined') {
  if (!window.ResizeObserver) {
    window.ResizeObserver = class ResizeObserver {
      observe() {}
      unobserve() {}
      disconnect() {}
    }
  }
}

// ── Mock sonner (toast) ────────────────────────────────────────────────────────

vi.mock('sonner', () => ({
  toast: Object.assign(vi.fn(), {
    success: vi.fn(),
    error: vi.fn(),
  }),
  Toaster: () => null,
}))

// ── Mock DisputeEvidenceDrawer ─────────────────────────────────────────────────
// Render a testid sentinel so we can detect "drawer open" without pulling in
// the full Sheet/shadcn tree (which has no jsdom match for portal).

vi.mock('@/components/payments/DisputeEvidenceDrawer', () => ({
  DisputeEvidenceDrawer: ({ open }: { open: boolean; onClose: () => void }) =>
    open ? <div data-testid="evidence-drawer-open" /> : null,
}))

// ── Types ──────────────────────────────────────────────────────────────────────

import type { StripeDisputeRow, DisputeDefensePackRow } from '@/lib/payments/contracts'

type DisputeWithPack = StripeDisputeRow & {
  dispute_defense_packs: Pick<
    DisputeDefensePackRow,
    | 'id'
    | 'signed_consent_url'
    | 'photo_release_url'
    | 'session_photos_urls'
    | 'chat_history_url'
    | 'deposit_policy_text'
    | 'receipt_url'
    | 'bundle_pdf_url'
    | 'generated_at'
  > | null
}

// ── Factories ──────────────────────────────────────────────────────────────────

function makeDispute(overrides: Partial<DisputeWithPack> = {}): DisputeWithPack {
  return {
    id: 'row-1',
    studio_id: 'studio-1',
    booking_id: null,
    dispute_id: 'dp_test_001',
    charge_id: 'ch_test_001',
    payment_intent_id: 'pi_test_001',
    amount_cents: 15000,
    currency: 'usd',
    reason: 'product_not_received',
    status: 'needs_response',
    evidence_due_by: new Date(Date.now() + 120 * 60 * 60 * 1000).toISOString(), // 5 days out
    defense_pack_status: 'pending',
    defense_pack_url: null,
    created_at: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString(),
    updated_at: new Date().toISOString(),
    dispute_defense_packs: null,
    ...overrides,
  }
}

function makePackRow(): DisputeWithPack['dispute_defense_packs'] {
  return {
    id: 'pack-1',
    signed_consent_url: 'https://storage.example.com/consent.pdf',
    photo_release_url: 'https://storage.example.com/release.pdf',
    session_photos_urls: [],
    chat_history_url: null,
    deposit_policy_text: 'All deposits are non-refundable.',
    receipt_url: 'https://storage.example.com/receipt.pdf',
    bundle_pdf_url: 'https://storage.example.com/bundle.pdf',
    generated_at: new Date().toISOString(),
  }
}

// ── Helpers ────────────────────────────────────────────────────────────────────

function stubFetch(disputes: DisputeWithPack[]) {
  vi.stubGlobal(
    'fetch',
    vi.fn().mockResolvedValue({
      ok: true,
      json: () => Promise.resolve({ data: disputes }),
    }),
  )
}

// ── Import after stubs ─────────────────────────────────────────────────────────

const { DisputesTab } = await import('@/components/payments/tabs/DisputesTab')

// ── Tests ──────────────────────────────────────────────────────────────────────

describe('DisputesTab', () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('renders empty state when no disputes', async () => {
    stubFetch([])

    render(<DisputesTab />)

    await waitFor(() => {
      expect(screen.getByText(/no disputes on record/i)).toBeInTheDocument()
    })

    // Serif "Disputes" heading present in empty state
    expect(screen.getByText('Disputes')).toBeInTheDocument()
  })

  it('renders urgency banner when dispute evidence_due_by < 72h', async () => {
    const urgentDispute = makeDispute({
      status: 'needs_response',
      defense_pack_status: 'ready',
      evidence_due_by: new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString(), // 48h
    })

    stubFetch([urgentDispute])

    render(<DisputesTab />)

    await waitFor(() => {
      // Banner text: "1 dispute requires evidence before <date>"
      expect(screen.getByText(/1 dispute requires evidence/i)).toBeInTheDocument()
    })
  })

  it('Submit now button calls submit endpoint and shows success toast', async () => {
    const readyDispute = makeDispute({
      defense_pack_status: 'ready',
      status: 'needs_response',
      evidence_due_by: new Date(Date.now() + 120 * 60 * 60 * 1000).toISOString(),
    })

    // First call: initial list fetch
    // Second call: submit POST
    // Third call: refresh list after submit
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve({ data: [readyDispute] }),
      })
      .mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve({ submitted: true }),
      })
      .mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve({ data: [{ ...readyDispute, defense_pack_status: 'submitted' }] }),
      })

    vi.stubGlobal('fetch', fetchMock)

    render(<DisputesTab />)

    // Wait for the Submit now button
    const submitBtn = await screen.findByRole('button', { name: /submit now/i })
    expect(submitBtn).toBeInTheDocument()

    fireEvent.click(submitBtn)

    await waitFor(() => {
      // Second call is the POST to the submit endpoint
      expect(fetchMock).toHaveBeenCalledWith(
        `/api/payments/disputes/${readyDispute.dispute_id}/submit`,
        expect.objectContaining({ method: 'POST' }),
      )
    })
  })

  it('View evidence button opens drawer', async () => {
    const submittedDispute = makeDispute({
      defense_pack_status: 'submitted',
      status: 'under_review',
      dispute_defense_packs: makePackRow(),
    })

    stubFetch([submittedDispute])

    render(<DisputesTab />)

    const viewBtn = await screen.findByRole('button', { name: /view evidence/i })
    expect(viewBtn).toBeInTheDocument()

    fireEvent.click(viewBtn)

    await waitFor(() => {
      expect(screen.getByTestId('evidence-drawer-open')).toBeInTheDocument()
    })
  })

  // Intentional skip: artist role tab hiding is not a component concern.
  // The DisputesTab renders with data for any authenticated user who reaches it.
  // Role-based tab visibility is controlled by the parent PaymentsPage navigation
  // config (featureKey guard + sidebar config) and is covered by E2E navigation
  // tests in tests/e2e/payments-tabs.spec.ts.
  it.skip('hides Disputes tab for artist role — covered by E2E navigation tests', () => {})
})

/**
 * Unit tests: components/settings/TaxDocumentsClient
 *
 * Coverage (3 tests):
 *  1. Empty state — "No tax documents generated yet."
 *  2. Generate button calls POST, triggers list refresh
 *  3. Download link renders with correct href and target="_blank"
 *
 * No DB required. Global fetch mocked per test.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, waitFor, fireEvent } from '@testing-library/react'

// ── Browser stubs ──────────────────────────────────────────────────────────────

if (typeof window !== 'undefined') {
  if (!window.ResizeObserver) {
    window.ResizeObserver = class ResizeObserver {
      observe() {}
      unobserve() {}
      disconnect() {}
    }
  }
}

// ── Mock sonner ────────────────────────────────────────────────────────────────

const toastSuccess = vi.fn()
const toastError = vi.fn()

vi.mock('sonner', () => ({
  toast: Object.assign(vi.fn(), {
    success: toastSuccess,
    error: toastError,
  }),
  Toaster: () => null,
}))

// ── Import ─────────────────────────────────────────────────────────────────────

import type { Nec1099ExportRow } from '@/components/settings/TaxDocumentsClient'

// Dynamic import after mocks are wired
const TaxDocumentsClientModule = await import('@/components/settings/TaxDocumentsClient')
const TaxDocumentsClient = TaxDocumentsClientModule.default

// ── Factories ──────────────────────────────────────────────────────────────────

function makeExportRow(overrides: Partial<Nec1099ExportRow> = {}): Nec1099ExportRow {
  return {
    id: 'export-1',
    year: 2025,
    artist_id: 'artist-uuid-001',
    total_paid_cents: 250000, // $2,500
    nec_threshold_met: true,
    source: 'stripe_connect',
    generated_at: '2026-01-15T10:00:00.000Z',
    csv_url: 'https://storage.example.com/1099-2025-artist-001.csv',
    ...overrides,
  }
}

// ── Tests ──────────────────────────────────────────────────────────────────────

describe('TaxDocumentsClient', () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('renders empty state when no exports', () => {
    render(<TaxDocumentsClient initialExports={[]} />)

    expect(screen.getByText(/no tax documents generated yet/i)).toBeInTheDocument()

    // "TAX DOCUMENTS" uppercase label heading (rendered as uppercase via CSS but text node is caps)
    expect(screen.getByText('TAX DOCUMENTS')).toBeInTheDocument()
  })

  it('Generate button calls POST endpoint and refreshes list', async () => {
    const currentYear = new Date().getFullYear()

    const postResponse = { year: currentYear, generated_count: 2 }
    const refreshedExport = makeExportRow({ year: currentYear })
    const getResponse = { exports: [refreshedExport] }

    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve(postResponse),
      })
      .mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve(getResponse),
      })

    vi.stubGlobal('fetch', fetchMock)

    render(<TaxDocumentsClient initialExports={[]} />)

    const generateBtn = screen.getByRole('button', { name: new RegExp(`generate ${currentYear}`, 'i') })
    fireEvent.click(generateBtn)

    await waitFor(() => {
      // POST to the tax-documents endpoint
      expect(fetchMock).toHaveBeenCalledWith(
        '/api/settings/payments/tax-documents',
        expect.objectContaining({
          method: 'POST',
          body: JSON.stringify({ year: currentYear }),
        }),
      )
    })

    // After success, list fetched again via GET
    await waitFor(() => {
      expect(fetchMock).toHaveBeenCalledWith('/api/settings/payments/tax-documents')
    })

    // Refreshed row now visible in table
    await waitFor(() => {
      expect(screen.getByText(String(currentYear))).toBeInTheDocument()
    })
  })

  it('Download link renders with correct href for each export row', () => {
    const csvUrl = 'https://storage.example.com/1099-2025.csv'
    const row = makeExportRow({ csv_url: csvUrl })

    render(<TaxDocumentsClient initialExports={[row]} />)

    const downloadLink = screen.getByRole('link', { name: /download csv/i })
    expect(downloadLink).toHaveAttribute('href', csvUrl)
    expect(downloadLink).toHaveAttribute('target', '_blank')
  })
})

/**
 * Integration tests: workers/cron/dispute-evidence-submitter
 *
 * Coverage (4 tests):
 *  1. Skips disputes with evidence_due_by > 25h away
 *  2. Submits ready disputes within 25h window
 *  3. Skips already-submitted disputes (defense_pack_status='submitted')
 *  4. Handles Stripe error gracefully — marks pack as failed via RPC
 *
 * Stripe + Supabase fully mocked. No network or DB required.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'

// ── Mock node-cron so schedule() is a no-op ────────────────────────────────────

vi.mock('node-cron', () => ({
  default: { schedule: vi.fn() },
  schedule: vi.fn(),
}))

// ── Stripe mock factory ────────────────────────────────────────────────────────

const stripeDisputesUpdate = vi.fn()

vi.mock('./shared/stripe', () => ({
  getStripe: () => ({
    disputes: {
      update: stripeDisputesUpdate,
    },
  }),
}))

// ── Supabase mock ──────────────────────────────────────────────────────────────
// The cron uses untyped cast chains:
//   supabase.from('stripe_disputes')...select().in().in().lt().limit()
//   supabase.from('dispute_defense_packs')...select().eq().maybeSingle()
//   supabase.rpc(RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS, {...})
//
// We wire all three surfaces per-test via the mutable `__mocks` object.

type ChainResult<T> = { data: T | null; error: { message: string } | null }

// Mutable state controlled per-test
const supabaseMock = {
  disputeQueryResult: [] as unknown[],
  defensePackResult: null as unknown,
  rpcResult: null as { message: string } | null,
}

// Builder that returns the chained query promise when .limit() is called
function makeFromChain(result: ChainResult<unknown[]>) {
  const chain = {
    select: () => chain,
    in: () => chain,
    lt: () => chain,
    limit: vi.fn().mockResolvedValue(result),
  }
  return chain
}

// Builder for the maybeSingle() chain
function makeSingleChain(result: ChainResult<unknown>) {
  const chain = {
    select: () => chain,
    eq: () => chain,
    maybeSingle: vi.fn().mockResolvedValue(result),
  }
  return chain
}

vi.mock('../lib/supabase', () => ({
  supabase: {
    from: (table: string) => {
      if (table === 'stripe_disputes') {
        return makeFromChain({
          data: supabaseMock.disputeQueryResult,
          error: null,
        })
      }
      if (table === 'dispute_defense_packs') {
        return makeSingleChain({
          data: supabaseMock.defensePackResult,
          error: null,
        })
      }
      return {}
    },
    rpc: vi.fn().mockImplementation(() =>
      Promise.resolve({ data: null, error: supabaseMock.rpcResult }),
    ),
  },
}))

// ── Mock lib/payments/contracts RPC constant ───────────────────────────────────

vi.mock('@/lib/payments/contracts', async () => {
  const actual = await vi.importActual<typeof import('@/lib/payments/contracts')>('@/lib/payments/contracts')
  return {
    ...actual,
    RPC: {
      ...(actual.RPC ?? {}),
      STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS: 'stripe_dispute_set_defense_pack_status',
    },
  }
})

// ── Import after mocks ─────────────────────────────────────────────────────────

const { submitReadyDisputePacks } = await import('@/workers/cron/dispute-evidence-submitter')

// Re-import supabase mock for spy assertions
const { supabase } = await import('../lib/supabase')

// ── Helpers ────────────────────────────────────────────────────────────────────

function futureIso(hours: number): string {
  return new Date(Date.now() + hours * 60 * 60 * 1000).toISOString()
}

function makeDisputeRow(evidenceDueBy: string, packStatus: string) {
  return {
    id: 'row-1',
    studio_id: 'studio-1',
    dispute_id: 'dp_test_001',
    charge_id: 'ch_test_001',
    evidence_due_by: evidenceDueBy,
    defense_pack_status: packStatus,
    defense_pack_url: 'https://storage.example.com/bundle.pdf',
  }
}

function makeDefensePackRow() {
  return {
    id: 'pack-1',
    dispute_id: 'dp_test_001',
    signed_consent_url: 'https://storage.example.com/consent.pdf',
    photo_release_url: 'https://storage.example.com/release.pdf',
    session_photos_urls: [],
    chat_history_url: null,
    deposit_policy_text: 'Non-refundable.',
    receipt_url: 'https://storage.example.com/receipt.pdf',
    bundle_pdf_url: null,
    generated_at: new Date().toISOString(),
  }
}

// ── Tests ──────────────────────────────────────────────────────────────────────

describe('submitReadyDisputePacks (dispute-evidence-submitter cron)', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    supabaseMock.disputeQueryResult = []
    supabaseMock.defensePackResult = null
    supabaseMock.rpcResult = null
  })

  it('skips disputes with evidence_due_by > 25h away', async () => {
    // The cron queries: .lt('evidence_due_by', cutoff) where cutoff = now + 25h
    // So a dispute at now + 30h is NOT returned by the query → empty result
    supabaseMock.disputeQueryResult = [] // query returns nothing — simulates the > 25h filter

    await submitReadyDisputePacks()

    // Stripe should never be called
    expect(stripeDisputesUpdate).not.toHaveBeenCalled()
  })

  it('submits ready disputes within 25h window', async () => {
    const dispute = makeDisputeRow(futureIso(10), 'ready')
    supabaseMock.disputeQueryResult = [dispute]
    supabaseMock.defensePackResult = makeDefensePackRow()

    stripeDisputesUpdate.mockResolvedValue({ id: 'dp_test_001' })

    await submitReadyDisputePacks()

    expect(stripeDisputesUpdate).toHaveBeenCalledWith(
      'dp_test_001',
      expect.objectContaining({ submit: true }),
    )
  })

  it('skips already-submitted disputes', async () => {
    // defense_pack_status='submitted' → query WHERE defense_pack_status IN ('ready')
    // won't return submitted rows. Simulate by returning empty result.
    supabaseMock.disputeQueryResult = [] // query excluded the submitted dispute

    await submitReadyDisputePacks()

    expect(stripeDisputesUpdate).not.toHaveBeenCalled()
  })

  it('handles Stripe error gracefully — marks pack as failed, does not throw', async () => {
    const dispute = makeDisputeRow(futureIso(10), 'ready')
    supabaseMock.disputeQueryResult = [dispute]
    supabaseMock.defensePackResult = makeDefensePackRow()

    // Stripe throws a network error
    stripeDisputesUpdate.mockRejectedValue(new Error('Stripe network error'))

    // Should NOT throw — cron continues
    await expect(submitReadyDisputePacks()).resolves.toBeUndefined()

