/**
 * Integration tests: workers/cron/dispute-evidence-submitter
 *
 * Coverage (4 tests):
 *  1. Skips disputes with evidence_due_by > 25h away (query returns empty)
 *  2. Submits ready disputes within 25h window — stripe.disputes.update called
 *  3. Skips already-submitted disputes (query returns empty, Stripe not called)
 *  4. Handles Stripe error — marks pack as failed via RPC, does not throw
 *
 * Strategy: mock the worker's three external surfaces —
 *   workers/lib/supabase (supabase client)
 *   workers/cron/shared/stripe (getStripe)
 *   @/lib/payments/contracts (RPC constant)
 *   node-cron (schedule = no-op)
 *
 * No network or DB required.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'

// ── node-cron — schedule is a no-op ───────────────────────────────────────────

vi.mock('node-cron', () => ({
  default: { schedule: vi.fn() },
  schedule: vi.fn(),
}))

// ── Stripe mock ────────────────────────────────────────────────────────────────

const stripeDisputesUpdate = vi.fn()

vi.mock('/Users/yashbaldha/Desktop/Boldteq App/InkOS/workers/cron/shared/stripe', () => ({
  getStripe: () => ({
    disputes: { update: stripeDisputesUpdate },
  }),
}))

// ── Supabase mock ──────────────────────────────────────────────────────────────
// The cron uses untyped cast chains:
//   supabase.from('stripe_disputes').select().in().in().lt().limit()
//   supabase.from('dispute_defense_packs').select().eq().maybeSingle()
//   supabase.rpc(RPC_NAME, args)

// Shared mutable state so each test can wire what the "DB" returns
const mockState = {
  disputeRows: [] as unknown[],
  defensePackRow: null as unknown,
}

// rpc spy — re-used across tests
const rpcSpy = vi.fn().mockResolvedValue({ data: null, error: null })

vi.mock('/Users/yashbaldha/Desktop/Boldteq App/InkOS/workers/lib/supabase', () => {
  function makeFromChain() {
    const chain: {
      select: () => typeof chain
      in: () => typeof chain
      lt: () => typeof chain
      eq: () => typeof chain
      limit: () => Promise<{ data: unknown[]; error: null }>
      maybeSingle: () => Promise<{ data: unknown; error: null }>
    } = {
      select() { return chain },
      in() { return chain },
      lt() { return chain },
      eq() { return chain },
      limit() {
        return Promise.resolve({ data: mockState.disputeRows, error: null })
      },
      maybeSingle() {
        return Promise.resolve({ data: mockState.defensePackRow, error: null })
      },
    }
    return chain
  }

  return {
    supabase: {
      from: (_table: string) => makeFromChain(),
      rpc: rpcSpy,
    },
  }
})

// ── lib/payments/contracts ─────────────────────────────────────────────────────

vi.mock('@/lib/payments/contracts', async () => {
  const actual = await vi.importActual<typeof import('@/lib/payments/contracts')>(
    '@/lib/payments/contracts',
  )
  return {
    ...actual,
    RPC: {
      ...(actual.RPC ?? {}),
      STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS: 'stripe_dispute_set_defense_pack_status',
    },
  }
})

// ── Import under test (after all mocks declared) ───────────────────────────────

const { submitReadyDisputePacks } = await import(
  '/Users/yashbaldha/Desktop/Boldteq App/InkOS/workers/cron/dispute-evidence-submitter'
)

// ── Helpers ────────────────────────────────────────────────────────────────────

function futureIso(hours: number): string {
  return new Date(Date.now() + hours * 60 * 60 * 1000).toISOString()
}

function makeDisputeRow(evidenceDueBy: string, packStatus: string) {
  return {
    id: 'row-1',
    studio_id: 'studio-1',
    dispute_id: 'dp_test_001',
    charge_id: 'ch_test_001',
    evidence_due_by: evidenceDueBy,
    defense_pack_status: packStatus,
    defense_pack_url: 'https://storage.example.com/bundle.pdf',
  }
}

function makeDefensePackRow() {
  return {
    id: 'pack-1',
    dispute_id: 'dp_test_001',
    signed_consent_url: 'https://storage.example.com/consent.pdf',
    photo_release_url: 'https://storage.example.com/release.pdf',
    session_photos_urls: [],
    chat_history_url: null,
    deposit_policy_text: 'Non-refundable.',
    receipt_url: 'https://storage.example.com/receipt.pdf',
    bundle_pdf_url: null,
    generated_at: new Date().toISOString(),
  }
}

// ── Tests ──────────────────────────────────────────────────────────────────────

describe('submitReadyDisputePacks', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    mockState.disputeRows = []
    mockState.defensePackRow = null
    rpcSpy.mockResolvedValue({ data: null, error: null })
  })

  it('skips disputes with evidence_due_by > 25h away', async () => {
    // The query filters .lt('evidence_due_by', cutoff) where cutoff = now + 25h.
    // A dispute at now + 30h is outside the window → query returns empty array.
    mockState.disputeRows = []

    await submitReadyDisputePacks()

    expect(stripeDisputesUpdate).not.toHaveBeenCalled()
  })

  it('submits ready disputes within 25h window', async () => {
    mockState.disputeRows = [makeDisputeRow(futureIso(10), 'ready')]
    mockState.defensePackRow = makeDefensePackRow()

    stripeDisputesUpdate.mockResolvedValue({ id: 'dp_test_001' })

    await submitReadyDisputePacks()

    expect(stripeDisputesUpdate).toHaveBeenCalledWith(
      'dp_test_001',
      expect.objectContaining({ submit: true }),
    )
  })

  it('skips already-submitted disputes', async () => {
    // defense_pack_status = 'submitted' → query WHERE status IN ('ready') excludes it.
    // Simulate by returning empty result (the real DB would do the same).
    mockState.disputeRows = []

    await submitReadyDisputePacks()

    expect(stripeDisputesUpdate).not.toHaveBeenCalled()
  })

  it('handles Stripe error gracefully — marks pack as failed, does not throw', async () => {
    mockState.disputeRows = [makeDisputeRow(futureIso(10), 'ready')]
    mockState.defensePackRow = makeDefensePackRow()

    stripeDisputesUpdate.mockRejectedValue(new Error('Stripe 500'))

    // Must NOT throw — cron continues
    await expect(submitReadyDisputePacks()).resolves.toBeUndefined()

    // RPC called to mark status 'failed'
    expect(rpcSpy).toHaveBeenCalledWith(
      'stripe_dispute_set_defense_pack_status',
      expect.objectContaining({
        p_dispute_id: 'dp_test_001',
        p_status: 'failed',
      }),
    )
  })
})

